1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { requireUser } from "./auth";
7	import { vpsTermPriceCents, addMonths } from "./billing-terms";
8	import { debitWallet, InsufficientBalanceError } from "./wallet";
9	
10	async function ownedServer(serverId: string) {
11	  const user = await requireUser();
12	  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
13	  if (!server) throw new Error("Not found");
14	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
15	  return { user, server };
16	}
17	
18	async function queueJob(
19	  serverId: string,
20	  type:
21	    | "SNAPSHOT_CREATE"
22	    | "SNAPSHOT_DELETE"
23	    | "SNAPSHOT_ROLLBACK"
24	    | "BACKUP_CREATE"
25	    | "RESIZE"
26	    | "PASSWORD_RESET",
27	  payload?: Record<string, unknown>
28	): Promise<{ error?: string }> {
29	  const pending = await db.job.count({
30	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
31	  });
32	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
33	  await db.job.create({ data: { type, serverId, payload: payload as any } });
34	  return {};
35	}
36	
37	// ---------- Snapshots ----------
38	
39	export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
40	  const { user, server } = await ownedServer(serverId);
41	  const clean = name.replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
42	  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
43	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
44	    return { error: "Server must be running or stopped." };
45	  }
46	  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
47	  if (!res.error) {
48	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
49	    revalidatePath(`/dashboard/servers/${serverId}`);
50	  }
51	  return res;
52	}
53	
54	export async function deleteSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
55	  const { user } = await ownedServer(serverId);
56	  const res = await queueJob(serverId, "SNAPSHOT_DELETE", { name });
57	  if (!res.error) {
58	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_delete", detail: `${serverId} ${name}` } });
59	    revalidatePath(`/dashboard/servers/${serverId}`);
60	  }
61	  return res;
62	}
63	
64	export async function rollbackSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
65	  const { user } = await ownedServer(serverId);
66	  const res = await queueJob(serverId, "SNAPSHOT_ROLLBACK", { name });
67	  if (!res.error) {
68	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_rollback", detail: `${serverId} ${name}` } });
69	    revalidatePath(`/dashboard/servers/${serverId}`);
70	  }
71	  return res;
72	}
73	
74	// ---------- Backups ----------
75	
76	export async function createBackup(serverId: string): Promise<{ error?: string }> {
77	  const { user, server } = await ownedServer(serverId);
78	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
79	    return { error: "Server must be running or stopped." };
80	  }
81	  const res = await queueJob(serverId, "BACKUP_CREATE");
82	  if (!res.error) {
83	    await db.auditLog.create({ data: { userId: user.id, action: "server.backup_create", detail: serverId } });
84	    revalidatePath(`/dashboard/servers/${serverId}`);
