88	
89	// ---------- Resize ----------
90	
91	export async function resizeServer(serverId: string, planId: string): Promise<{ error?: string }> {
92	  const { user, server } = await ownedServer(serverId);
93	  const newPlan = await db.plan.findUnique({ where: { id: planId } });
94	  if (!newPlan?.active) return { error: "Plan not available." };
95	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
96	  if (newPlan.diskGB < server.plan.diskGB) {
97	    return { error: "Disk storage can only grow — choose a plan with equal or larger disk." };
98	  }
99	  if (newPlan.priceCents < server.plan.priceCents) {
100	    return { error: "Downgrades aren't self-service yet — please contact support." };
101	  }
102	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
103	
104	  // Prorate the upgrade: charge the price difference for the unused portion of the
105	  // current billing term so mid-term upgrades aren't free (paid servers only).
106	  let prorateCents = 0;
107	  if (!server.isFree && server.expiresAt) {
108	    const now = Date.now();
109	    const periodStart = addMonths(server.expiresAt, -server.termMonths).getTime();
110	    const periodMs = server.expiresAt.getTime() - periodStart;
111	    const remainingFraction = periodMs > 0 ? Math.max(0, Math.min(1, (server.expiresAt.getTime() - now) / periodMs)) : 0;
112	    const deltaFullTerm =
113	      vpsTermPriceCents(newPlan.priceCents, server.termMonths) - vpsTermPriceCents(server.plan.priceCents, server.termMonths);
114	    prorateCents = Math.round(deltaFullTerm * remainingFraction);
115	    if (prorateCents > 0 && user.balanceCents < prorateCents) {
116	      return {
117	        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term. Top up your wallet first.`,
118	      };
119	    }
120	  }
121	
122	  const pending = await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
123	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
124	
125	  try {
126	    await db.$transaction(async (tx) => {
127	      if (prorateCents > 0) {
128	        await debitWallet(tx, server.userId, prorateCents);
129	        await tx.walletTransaction.create({
130	          data: { userId: server.userId, amountCents: -prorateCents, description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}` },
131	        });
132	      }
133	      await tx.job.create({ data: { type: "RESIZE", serverId, payload: { planId } as any } });
134	      await tx.auditLog.create({
135	        data: { userId: user.id, action: "server.resize", detail: `${serverId} -> ${newPlan.slug} prorate=${prorateCents}` },
136	      });
137	    });
138	  } catch (e) {
139	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
140	    throw e;
141	  }
142	  revalidatePath(`/dashboard/servers/${serverId}`);
143	  return {};
144	}
145	
146	// ---------- Root password reset ----------
147	
148	export async function resetRootPassword(serverId: string): Promise<{ error?: string }> {
149	  const { user, server } = await ownedServer(serverId);
150	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
151	    return { error: "Server must be running or stopped to reset its password." };
152	  }
153	  const res = await queueJob(serverId, "PASSWORD_RESET");
154	  if (!res.error) {
155	    await db.auditLog.create({
156	      data: { userId: user.id, action: "server.password_reset", detail: serverId },
157	    });
158	    revalidatePath(`/dashboard/servers/${serverId}`);
159	    revalidatePath(`/admin/servers/${serverId}`);
160	  }
161	  return res;
162	}
163	
164	// ---------- Port forwarding (firewall/networking) ----------
165	
166	import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
167	const MAX_FORWARDS_PER_SERVER = 10;
168	
169	export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
170	  const serverId = String(formData.get("serverId") ?? "");
171	  const { user, server } = await ownedServer(serverId);
172	  const parsed = z
173	    .object({
174	      guestPort: z.coerce.number().int().min(1).max(65535),
175	      protocol: z.enum(["tcp", "udp"]),
176	    })
177	    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
178	  if (!parsed.success) return { error: "Invalid port." };
179	
180	  const count = await db.portForward.count({ where: { serverId } });
181	  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };
182	
183	  const used = new Set([
184	    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
185	    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
186	  ]);
187	  let publicPort = 0;
188	  for (let p = PF_MIN; p <= PF_MAX; p++) {
189	    if (!used.has(p)) { publicPort = p; break; }
190	  }
191	  if (!publicPort) return { error: "No public ports available." };
192	
193	  await db.portForward.create({
194	    data: { serverId, publicPort, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
195	  });
196	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
197	  await db.auditLog.create({
198	    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
199	  });
200	  revalidatePath(`/dashboard/servers/${serverId}`);
201	  return {};
202	}
203	
204	export async function deletePortForward(serverId: string, forwardId: string) {
205	  const { user } = await ownedServer(serverId);
206	  await db.portForward.deleteMany({ where: { id: forwardId, serverId } });
207	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
208	  await db.auditLog.create({
209	    data: { userId: user.id, action: "server.portforward_delete", detail: `${serverId} ${forwardId}` },
210	  });
211	  revalidatePath(`/dashboard/servers/${serverId}`);
212	}
