1	/**
2	 * Billing term definitions + discount math, shared by ordering, renewal,
3	 * the deploy wizard, invoices and the domain flow. Discounts are the platform's
4	 * promo (longer commitment = cheaper); tune here (or later via admin Settings).
5	 */
6	
7	export type VpsTerm = { months: number; label: string; short: string; discountPct: number };
8	
9	export const VPS_TERMS: VpsTerm[] = [
10	  { months: 1, label: "Monthly", short: "1 mo", discountPct: 0 },
11	  { months: 12, label: "Annual", short: "1 yr", discountPct: 10 },
12	  { months: 24, label: "Biennial", short: "2 yr", discountPct: 15 },
13	  { months: 36, label: "Triennial", short: "3 yr", discountPct: 20 },
14	];
15	
16	export function vpsTerm(months: number): VpsTerm {
17	  return VPS_TERMS.find((t) => t.months === months) ?? VPS_TERMS[0];
18	}
19	
20	/** Total charge (cents) for a plan over a term, discount applied. */
21	export function vpsTermPriceCents(monthlyCents: number, months: number): number {
22	  const t = vpsTerm(months);
23	  return Math.round(monthlyCents * months * (1 - t.discountPct / 100));
24	}
25	
26	/** Effective monthly-equivalent price after the term discount (for "$/mo" display). */
27	export function vpsEffectiveMonthly(monthlyCents: number, months: number): number {
28	  return Math.round(vpsTermPriceCents(monthlyCents, months) / months);
29	}
30	
31	export type DomainTerm = { years: number; label: string; discountPct: number };
32	
33	export const DOMAIN_TERMS: DomainTerm[] = [
34	  { years: 1, label: "1 year", discountPct: 0 },
35	  { years: 2, label: "2 years", discountPct: 5 },
36	  { years: 3, label: "3 years", discountPct: 10 },
37	];
38	
39	export function domainTerm(years: number): DomainTerm {
40	  return DOMAIN_TERMS.find((t) => t.years === years) ?? DOMAIN_TERMS[0];
41	}
42	
43	/** Total charge (cents) for a domain over N years, discount applied. */
44	export function domainTermPriceCents(perYearCents: number, years: number): number {
45	  const t = domainTerm(years);
46	  return Math.round(perYearCents * years * (1 - t.discountPct / 100));
47	}
48	
49	/** Add whole months to a date (UTC-safe enough for billing windows). */
50	export function addMonths(from: Date, months: number): Date {
51	  const d = new Date(from);
52	  d.setMonth(d.getMonth() + months);
53	  return d;
54	}
