1	"use client";
2	
3	import { useState, useTransition } from "react";
4	import { useRouter } from "next/navigation";
5	import { toggleAutoUpdate, triggerGameUpdate } from "@/lib/actions-server-ops";
6	
7	/**
8	 * Game-server auto-update controls: a toggle for `Server.autoUpdate` plus an
9	 * "Update now" button that enqueues a one-off GAME_UPDATE job.
10	 */
11	export function GameAutoUpdate({
12	  serverId,
13	  gameName,
14	  autoUpdate,
15	  canUpdate,
16	  busy,
17	}: {
18	  serverId: string;
19	  gameName: string;
20	  autoUpdate: boolean;
21	  /** true when the VM is RUNNING (required for the SSH update) */
22	  canUpdate: boolean;
23	  /** true when another job is in flight */
24	  busy: boolean;
25	}) {
26	  const router = useRouter();
27	  const [enabled, setEnabled] = useState(autoUpdate);
28	  const [error, setError] = useState<string | null>(null);
29	  const [savingToggle, startToggle] = useTransition();
30	  const [updating, startUpdate] = useTransition();
31	
32	  function flip() {
33	    const next = !enabled;
34	    setEnabled(next); // optimistic
35	    startToggle(async () => {
36	      setError(null);
37	      const res = await toggleAutoUpdate(serverId, next);
38	      if (res?.error) {
39	        setEnabled(!next); // revert
40	        setError(res.error);
41	      }
42	    });
43	  }
44	
45	  function updateNow() {
46	    startUpdate(async () => {
47	      setError(null);
48	      const res = await triggerGameUpdate(serverId);
49	      if (res?.error) setError(res.error);
50	      else router.refresh();
51	    });
52	  }
53	
54	  return (
55	    <div className="card">
56	      <div className="flex flex-wrap items-start justify-between gap-4">
57	        <div>
58	          <h2 className="font-semibold">Game updates</h2>
59	          <p className="mt-1 max-w-md text-sm text-slate-400">
60	            Keep your {gameName} server current. Updates run the game&apos;s update command over SSH
61	            and restart the service — expect a short interruption while it applies.
62	          </p>
63	        </div>
64	        <button
65	          className="btn-primary"
66	          disabled={updating || busy || !canUpdate}
67	          onClick={updateNow}
68	          title={!canUpdate ? "Server must be running" : undefined}
69	        >
70	          {updating ? "Queueing…" : "Update now"}
71	        </button>
72	      </div>
73	
74	      <div className="divider" />
75	
76	      <label className="flex cursor-pointer items-center justify-between gap-4">
77	        <span className="text-sm">
78	          <span className="font-medium">Automatic updates</span>
79	          <span className="mt-0.5 block text-xs text-slate-500">
80	            When on, we periodically update this server to the latest version in the background.
81	          </span>
