51	  // Restart the named service, then a "<family>-server" variant, then any unit
52	  // whose name contains the family; never hard-fail.
53	  const restart =
54	    `systemctl restart ${svc} 2>/dev/null || ` +
55	    `systemctl restart ${svc}-server 2>/dev/null || ` +
56	    `svc=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${family} | head -1 | awk '{print $1}'); ` +
