"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { vpsTermPriceCents, addMonths } from "./billing-terms";

/**
 * Server lifecycle "extras" — scheduled backups, reinstall-to-a-different-OS and
 * resize-down. These complement the primary flows in `lib/actions-server.ts`
 * (create backup, resize-up, reinstall-same-OS). Every op is ownership-checked
 * and respects the "one in-flight job per server" invariant.
 */

/** Allowed scheduled-backup cadences (hours). Kept small + human-friendly. */
export const BACKUP_INTERVAL_CHOICES = [12, 24, 48, 72, 168] as const;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { plan: true, osTemplate: true },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function hasInflightJob(serverId: string): Promise<boolean> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  return pending > 0;
}

// ---------- 1. Scheduled backups ----------

/**
 * Enable/disable recurring backups and set the cadence. When enabling we do NOT
 * touch `lastAutoBackup` — a null/stale value simply lets the sweep run the
 * first backup on its next pass.
 */
export async function setBackupSchedule(
  serverId: string,
  enabled: boolean,
  intervalHours: number
): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);

  if (enabled && !BACKUP_INTERVAL_CHOICES.includes(intervalHours as any)) {
    return { error: "Choose a valid backup interval." };
  }

  await db.server.update({
    where: { id: server.id },
    data: {
      autoBackup: enabled,
      backupIntervalHours: enabled ? intervalHours : null,
    },
  });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.backup_schedule",
      detail: enabled ? `${serverId} every ${intervalHours}h` : `${serverId} disabled`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- 2. Reinstall to a different OS ----------

/**
 * Switch the server to a different OS image and reinstall. This ERASES all data:
 * the worker's REINSTALL handler destroys the VM and re-provisions it from
 * `Server.osTemplateId`, so we persist the new template BEFORE enqueuing.
 */
export async function reinstallToOs(
  serverId: string,
  osTemplateId: string
): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);

  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to reinstall." };
  }

  const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
  if (!os?.active) return { error: "That operating system isn't available." };
  if (os.id === server.osTemplateId) {
    return { error: "This server is already running that operating system." };
  }
  if (server.plan.ramMB < os.minRamMB) {
    return { error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM — your plan has ${server.plan.ramMB / 1024} GB.` };
  }
  if (server.plan.diskGB < os.minDiskGB) {
    return { error: `${os.name} needs at least ${os.minDiskGB} GB disk — your plan has ${server.plan.diskGB} GB.` };
  }

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  // Persist the target OS first so the REINSTALL handler (which re-provisions
  // from Server.osTemplateId) rebuilds onto the new image, then enqueue.
  await db.server.update({ where: { id: server.id }, data: { osTemplateId: os.id } });
  await db.job.create({ data: { type: "REINSTALL", serverId } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.reinstall_os",
      detail: `${serverId} -> ${os.slug} (was ${server.osTemplate.slug})`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- 3. Resize-down ----------

/**
 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
 * otherwise). A prorated credit for the price difference over the remaining term
 * is returned to the wallet.
 */
export async function resizeServerDown(
  serverId: string,
  newPlanId: string
): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);

  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
  if (!newPlan?.active) return { error: "Plan not available." };
  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };

  // This action is downgrades only — upgrades go through resizeServer().
  if (newPlan.priceCents >= server.plan.priceCents) {
    return { error: "This is not a smaller plan — use the upgrade flow instead." };
  }
  // Disk can't shrink destructively; block the move rather than lose data.
  if (newPlan.diskGB < server.plan.diskGB) {
    return {
      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
    };
  }

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  // Prorated credit: refund the price difference for the unused portion of the
  // current billing term (paid servers only; free servers get nothing to refund).
  let creditCents = 0;
  if (!server.isFree && server.expiresAt) {
    const now = Date.now();
    const periodStart = addMonths(server.expiresAt, -server.termMonths).getTime();
    const periodMs = server.expiresAt.getTime() - periodStart;
    const remainingFraction =
      periodMs > 0
        ? Math.max(0, Math.min(1, (server.expiresAt.getTime() - now) / periodMs))
        : 0;
    const deltaFullTerm =
      vpsTermPriceCents(server.plan.priceCents, server.termMonths) -
      vpsTermPriceCents(newPlan.priceCents, server.termMonths);
    creditCents = Math.max(0, Math.round(deltaFullTerm * remainingFraction));
  }

  await db.$transaction([
    ...(creditCents > 0
      ? [
          db.user.update({
            where: { id: server.userId },
            data: { balanceCents: { increment: creditCents } },
          }),
          db.walletTransaction.create({
            data: {
              userId: server.userId,
              amountCents: creditCents,
              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
            },
          }),
        ]
      : []),
    db.job.create({ data: { type: "RESIZE", serverId, payload: { planId: newPlan.id } as any } }),
    db.auditLog.create({
      data: {
        userId: user.id,
        action: "server.resize_down",
        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
      },
    }),
  ]);

  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

import { db } from "../lib/db";

/**
 * Scheduled-backup sweep.
 *
 * `scheduledBackupSweep` finds RUNNING servers that opted into recurring backups
 * (`autoBackup=true`) whose last automatic backup is older than their configured
 * cadence (or which have never had one), and enqueues a BACKUP_CREATE job for
 * each — de-duping on any in-flight job so it's safe to call on a timer.
 *
 * NOTE: `worker/index.ts` owns the job loop; it already knows how to run
 * BACKUP_CREATE jobs. Wire this sweep into the main loop on a timer, e.g.:
 *
 *   import { scheduledBackupSweep } from "./backup-schedule";
 *   if (Date.now() - lastBackupSweep > 15 * 60_000) {
 *     lastBackupSweep = Date.now();
 *     try { await scheduledBackupSweep(); } catch (e) { console.error(e); }
 *   }
 */
export async function scheduledBackupSweep(): Promise<void> {
  const now = Date.now();

  const candidates = await db.server.findMany({
    where: {
      status: "RUNNING",
      autoBackup: true,
      backupIntervalHours: { not: null },
    },
    select: {
      id: true,
      hostname: true,
      backupIntervalHours: true,
      lastAutoBackup: true,
    },
  });
  if (candidates.length === 0) return;

  let enqueued = 0;
  for (const s of candidates) {
    const intervalMs = (s.backupIntervalHours ?? 0) * 60 * 60_000;
    if (intervalMs <= 0) continue;

    // Due if it has never run, or the cadence has elapsed since the last one.
    const dueAt = s.lastAutoBackup ? s.lastAutoBackup.getTime() + intervalMs : 0;
    if (now < dueAt) continue;

    // Respect the one-in-flight-job-per-server invariant.
    const inflight = await db.job.count({
      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (inflight > 0) continue;

    await db.job.create({ data: { type: "BACKUP_CREATE", serverId: s.id } });
    // Mark the schedule as satisfied now so a slow backup / a second sweep pass
    // doesn't pile up duplicate jobs; the timestamp anchors the next window.
    await db.server.update({
      where: { id: s.id },
      data: { lastAutoBackup: new Date() },
    });
    enqueued++;
  }

  if (enqueued > 0) console.log(`[backup-schedule] sweep enqueued ${enqueued} backup job(s)`);
}

"use client";

import { useState, useTransition } from "react";
import { setBackupSchedule } from "@/lib/actions-server-lifecycle";

const INTERVALS: { hours: number; label: string }[] = [
  { hours: 12, label: "Every 12 hours" },
  { hours: 24, label: "Daily" },
  { hours: 48, label: "Every 2 days" },
  { hours: 72, label: "Every 3 days" },
  { hours: 168, label: "Weekly" },
];

export function BackupSchedule({
  serverId,
  autoBackup,
  backupIntervalHours,
  lastAutoBackup,
}: {
  serverId: string;
  autoBackup: boolean;
  backupIntervalHours: number | null;
  /** ISO string of the last automatic backup, or null */
  lastAutoBackup: string | null;
}) {
  const [enabled, setEnabled] = useState(autoBackup);
  const [interval, setInterval] = useState<number>(backupIntervalHours ?? 24);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const [pending, start] = useTransition();

  function save(nextEnabled: boolean, nextInterval: number) {
    start(async () => {
      setError(null);
      setSaved(false);
      const res = await setBackupSchedule(serverId, nextEnabled, nextInterval);
      if (res?.error) {
        setError(res.error);
        setEnabled(autoBackup); // revert toggle to server truth on failure
      } else {
        setSaved(true);
      }
    });
  }

  function flip() {
    const next = !enabled;
    setEnabled(next); // optimistic
    save(next, interval);
  }

  return (
    <div className="card">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h2 className="font-semibold">Scheduled backups</h2>
          <p className="mt-1 max-w-md text-sm text-slate-400">
            Automatically create a full-image backup on a recurring schedule. Backups land on the
            separate backup pool — independent from your server&apos;s NVMe storage.
          </p>
        </div>
        <button
          type="button"
          role="switch"
          aria-checked={enabled}
          disabled={pending}
          onClick={flip}
          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
            enabled ? "bg-brand-500" : "bg-white/15"
          } ${pending ? "opacity-60" : ""}`}
        >
          <span
            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
              enabled ? "translate-x-5" : "translate-x-0.5"
            }`}
          />
        </button>
      </div>

      {enabled && (
        <>
          <div className="divider" />
          <label className="block text-sm">
            <span className="mb-1.5 block font-medium">Backup frequency</span>
            <select
              className="input"
              value={interval}
              disabled={pending}
              onChange={(e) => {
                const v = Number(e.target.value);
                setInterval(v);
                save(true, v);
              }}
            >
              {INTERVALS.map((i) => (
                <option key={i.hours} value={i.hours}>
                  {i.label}
                </option>
              ))}
            </select>
          </label>
          <p className="mt-3 text-xs text-slate-500">
            Last automatic backup:{" "}
            {lastAutoBackup
              ? new Date(lastAutoBackup).toISOString().slice(0, 16).replace("T", " ") + " UTC"
              : "none yet — the first one runs on the next sweep."}
          </p>
        </>
      )}

      {error && <p className="mt-3 text-sm text-red-400">{error}</p>}
      {saved && !error && !pending && (
        <p className="mt-3 text-sm text-emerald-400">Backup schedule saved.</p>
      )}
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { reinstallToOs } from "@/lib/actions-server-lifecycle";

type OsRow = {
  id: string;
  name: string;
  family: string;
  version: string;
  minRamMB: number;
  minDiskGB: number;
};

export function ReinstallOs({
  serverId,
  currentOsTemplateId,
  currentOsName,
  planRamMB,
  planDiskGB,
  templates,
  disabled,
}: {
  serverId: string;
  currentOsTemplateId: string;
  currentOsName: string;
  planRamMB: number;
  planDiskGB: number;
  templates: OsRow[];
  disabled?: boolean;
}) {
  const [selected, setSelected] = useState<string>("");
  const [confirmText, setConfirmText] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const target = templates.find((t) => t.id === selected);
  const fits = target ? planRamMB >= target.minRamMB && planDiskGB >= target.minDiskGB : true;
  const confirmed = confirmText.trim().toUpperCase() === "ERASE";

  return (
    <div className="card">
      <h2 className="font-semibold">Reinstall with a different OS</h2>
      <p className="mt-1 max-w-xl text-sm text-slate-400">
        Rebuild this server onto a fresh operating system. It currently runs{" "}
        <span className="font-medium text-slate-200">{currentOsName}</span>.
      </p>

      <div className="mt-4 rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-300">
        <span className="font-semibold">This erases all data.</span> The current disk is destroyed
        and replaced with a clean image. Snapshots and backups are lost. Take a backup first if you
        need anything off this server.
      </div>

      <div className="mt-4 space-y-4">
        <label className="block text-sm">
          <span className="mb-1.5 block font-medium">New operating system</span>
          <select
            className="input"
            value={selected}
            disabled={pending || disabled}
            onChange={(e) => {
              setSelected(e.target.value);
              setError(null);
            }}
          >
            <option value="">Select an OS…</option>
            {templates
              .filter((t) => t.id !== currentOsTemplateId)
              .map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name}
                  {t.version ? ` ${t.version}` : ""}
                </option>
              ))}
          </select>
        </label>

        {target && !fits && (
          <p className="text-sm text-amber-300">
            {target.name} needs at least {target.minRamMB / 1024} GB RAM and {target.minDiskGB} GB
            disk. Your plan has {planRamMB / 1024} GB RAM / {planDiskGB} GB disk — resize up first.
          </p>
        )}

        <label className="block text-sm">
          <span className="mb-1.5 block font-medium">
            Type <span className="font-mono text-red-300">ERASE</span> to confirm
          </span>
          <input
            className="input"
            value={confirmText}
            disabled={pending || disabled}
            onChange={(e) => setConfirmText(e.target.value)}
            placeholder="ERASE"
            autoComplete="off"
          />
        </label>

        <button
          className="btn-danger"
          disabled={!target || !fits || !confirmed || pending || disabled}
          onClick={() => {
            if (!target) return;
            if (
              !window.confirm(
                `Reinstall this server with ${target.name}? This permanently erases all data on the server.`
              )
            )
              return;
            start(async () => {
              setError(null);
              const res = await reinstallToOs(serverId, target.id);
              if (res?.error) setError(res.error);
              else {
                setSelected("");
                setConfirmText("");
              }
            });
          }}
        >
          {pending ? "Queueing reinstall…" : target ? `Erase & reinstall ${target.name}` : "Select an OS"}
        </button>

        {error && <p className="text-sm text-red-400">{error}</p>}
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { resizeServerDown } from "@/lib/actions-server-lifecycle";
import { fmtMoney } from "@/components/ui/primitives";
import { vpsTermPriceCents, addMonths } from "@/lib/billing-terms";

type PlanRow = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
};

export function ResizeDown({
  serverId,
  currentPlanId,
  currentDiskGB,
  currentPriceCents,
  termMonths,
  expiresAt,
  isFree,
  plans,
  disabled,
}: {
  serverId: string;
  currentPlanId: string;
  currentDiskGB: number;
  currentPriceCents: number;
  termMonths: number;
  /** ISO string of the current term end, or null */
  expiresAt: string | null;
  isFree: boolean;
  plans: PlanRow[];
  disabled?: boolean;
}) {
  const [selected, setSelected] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  // Only cheaper plans are downgrade candidates.
  const smaller = plans.filter((p) => p.id !== currentPlanId && p.priceCents < currentPriceCents);
  const target = smaller.find((p) => p.id === selected) ?? null;

  // Estimated prorated credit (mirrors resizeServerDown on the server).
  function estimateCredit(newPriceCents: number): number {
    if (isFree || !expiresAt) return 0;
    const end = new Date(expiresAt).getTime();
    const periodStart = addMonths(new Date(expiresAt), -termMonths).getTime();
    const periodMs = end - periodStart;
    const remainingFraction =
      periodMs > 0 ? Math.max(0, Math.min(1, (end - Date.now()) / periodMs)) : 0;
    const deltaFullTerm =
      vpsTermPriceCents(currentPriceCents, termMonths) - vpsTermPriceCents(newPriceCents, termMonths);
    return Math.max(0, Math.round(deltaFullTerm * remainingFraction));
  }

  const credit = target ? estimateCredit(target.priceCents) : 0;

  return (
    <div className="card space-y-5">
      <div>
        <h2 className="font-semibold">Downsize your plan</h2>
        <p className="mt-1 max-w-xl text-sm text-slate-400">
          Move to a smaller, cheaper plan. CPU and RAM shrink on the next power cycle. Disk storage
          can&apos;t shrink, so only plans whose disk is at least your current {currentDiskGB} GB are
          selectable. We credit the prorated difference for the rest of your term back to your
          wallet.
        </p>
      </div>

      {error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
          {error}
        </div>
      )}

      {smaller.length === 0 ? (
        <p className="text-sm text-slate-400">
          You&apos;re already on the smallest plan — there&apos;s nothing smaller to move to.
        </p>
      ) : (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {smaller.map((p) => {
            const diskShrinks = p.diskGB < currentDiskGB;
            const active = selected === p.id;
            return (
              <button
                key={p.id}
                type="button"
                disabled={diskShrinks || pending || disabled}
                title={
                  diskShrinks
                    ? `Disk can't shrink — this plan has ${p.diskGB} GB, your server uses a ${currentDiskGB} GB disk.`
                    : undefined
                }
                onClick={() => setSelected(active ? null : p.id)}
                className={`card p-4 text-left transition-all ${
                  diskShrinks
                    ? "cursor-not-allowed opacity-40"
                    : active
                      ? "cursor-pointer border-accent-blue ring-1 ring-accent-blue"
                      : "cursor-pointer hover:border-white/20"
                }`}
              >
                <div className="flex items-baseline justify-between">
                  <span className="font-semibold">{p.name}</span>
                  <span className="text-lg font-bold">
                    {fmtMoney(p.priceCents)}
                    <span className="text-xs font-normal text-slate-400">/mo</span>
                  </span>
                </div>
                <p className="mt-1 text-sm text-slate-400">
                  {p.cpuCores} vCPU · {p.ramMB / 1024} GB RAM · {p.diskGB} GB NVMe · {p.bandwidthTB} TB
                </p>
                {diskShrinks && (
                  <p className="mt-2 text-xs text-slate-500">Smaller disk — can&apos;t shrink</p>
                )}
              </button>
            );
          })}
        </div>
      )}

      {smaller.length > 0 && (
        <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
          <p className="text-xs text-slate-400">
            {target && credit > 0 ? (
              <>
                Estimated credit back to your wallet:{" "}
                <span className="font-semibold text-emerald-400">{fmtMoney(credit)}</span>. Requires a
                power cycle.
              </>
            ) : (
              "Downsizing requires a power cycle. The new price applies at your next renewal."
            )}
          </p>
          <button
            className="btn-primary"
            disabled={!target || pending || disabled}
            onClick={() => {
              if (!target) return;
              if (
                !window.confirm(
                  `Downsize this server to ${target.name} (${fmtMoney(target.priceCents)}/mo)?${
                    credit > 0 ? ` ${fmtMoney(credit)} will be credited to your wallet.` : ""
                  } The server will be power-cycled.`
                )
              )
                return;
              start(async () => {
                setError(null);
                const res = await resizeServerDown(serverId, target.id);
                if (res?.error) setError(res.error);
                else setSelected(null);
              });
            }}
          >
            {pending ? "Downsizing…" : target ? `Downsize to ${target.name}` : "Select a plan"}
          </button>
        </div>
      )}
    </div>
  );
}

